date; echo "TZ=$TZ"; cat > /tmp/render.mjs <<'EOF'
import fs from 'node:fs';
const [,, src, title] = process.argv;
const lines = fs.readFileSync(src, 'utf8').split('\n').filter(Boolean).map(l => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean);
const pad = n => String(n).padStart(2, '0');
const fmt = ts => { const d = new Date(ts); return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())} ${pad(d.getHours())}:${pad(d.getMinutes())}:${pad(d.getSeconds())}`; };
const out = [`# ${title}`, '', 'Rendered from the raw transcript beside this file. User and assistant text in full; tool calls shown as one line each; tool results omitted.', ''];
for (const e of lines) {
  if (e.type !== 'user' && e.type !== 'assistant') continue;
  const c = e.message?.content;
  if (c == null) continue;
  const who = e.type === 'user' ? 'Izzy' : 'Claude';
  if (typeof c === 'string') { if (c.trim()) out.push('', `## ${who} · ${fmt(e.timestamp)}`, '', c.trim(), ''); continue; }
  const texts = c.filter(b => b.type === 'text' && b.text?.trim()).map(b => b.text.trim());
  const tools = c.filter(b => b.type === 'tool_use');
  if (texts.length) {
    // skip injected skill/system payloads that arrive as user text
    const t = texts.join('\n\n');
    if (who === 'Izzy' && /^Base directory for this skill/.test(t)) continue;
    out.push('', `## ${who} · ${fmt(e.timestamp)}`, '', t, '');
  }
  for (const t of tools) {
    const inp = t.input || {};
    const desc = t.name === 'Bash' && inp.description ? inp.description : JSON.stringify(inp);
    out.push('', `> tool \`${t.name}\`: ${desc}`, '');
  }
}
fs.writeFileSync(1, out.join('\n').replace(/\n{3,}/g, '\n\n') + '\n');
EOF
